steps.solution:
function makePairs(students, mentors) {
  const meetings = []
  for (const student of students) {
    for (const mentor of mentors) {
      meetings.push(student + ' + ' + mentor)
    }
  }
  return meetings
}

console.log(makePairs(['Ana', 'Bo'], ['Dr. Lee']))
